"""Regenerates the MASK-1 sample originals from the committed reference cut-outs.

    python tests/fixtures/mask_sample/_generate.py

reference/<name>.png are fc-mobile's committed synthetic stand-ins
(src/dev-fixtures/synthetic, generated by its scripts/synthetic-fixtures.mjs:
flat geometric figures, no photos) -- the "July reference" cut-outs for this
sample: RGBA, the alpha is the reference matte. originals/<entry>.png are
those cut-outs composited over a studio backdrop: what a store photo of the
figure would look like, and what the mask lane receives. No store image is
ever fetched or committed.

madoka-black-dress reproduces the July failure case
(fc-design-assets/madoka-matte-basekept.png: a black dress on a black marble
studio floor): the madoka stand-in with its dress and hair recoloured near
black, over a near-black mottled backdrop.
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np
from PIL import Image

HERE = Path(__file__).resolve().parent


def _over(ref: np.ndarray, backdrop: np.ndarray) -> np.ndarray:
    a = ref[..., 3:4].astype(np.float64) / 255.0
    out = ref[..., :3].astype(np.float64) * a + backdrop.astype(np.float64) * (1.0 - a)
    return np.clip(np.round(out), 0, 255).astype(np.uint8)


def _flat(ref: np.ndarray, rgb: tuple[int, int, int]) -> np.ndarray:
    return np.broadcast_to(np.array(rgb, dtype=np.uint8), ref.shape[:2] + (3,)).copy()


def _marble(ref: np.ndarray) -> np.ndarray:
    h, w = ref.shape[:2]
    y, x = np.mgrid[0:h, 0:w]
    vein = (np.sin(x / 23.0 + y / 41.0) + np.sin(x / 7.0 - y / 13.0)) * 2.0
    base = 14.0 + vein
    return np.clip(np.dstack([base, base, base + 2.0]), 0, 255).astype(np.uint8)


def _black_dress(ref: np.ndarray) -> np.ndarray:
    out = ref.copy()
    rgb = out[..., :3].astype(np.int32)
    pink = (rgb[..., 0] > 200) & (rgb[..., 1] < 160)
    white = (rgb[..., 0] > 230) & (rgb[..., 1] > 230)
    out[pink, :3] = (34, 22, 40)  # hair and bodice, near black
    out[white, :3] = (24, 20, 28)  # skirt, near black
    return out


def main() -> None:
    manifest = json.loads((HERE / "manifest.json").read_text())
    (HERE / "originals").mkdir(exist_ok=True)
    for entry in manifest["entries"]:
        ref = np.asarray(
            Image.open(HERE / "reference" / f"{entry['reference']}.png").convert("RGBA")
        )
        if entry.get("variant") == "black_dress":
            ref = _black_dress(ref)
        backdrop = (
            _marble(ref) if entry["backdrop"] == "marble" else _flat(ref, tuple(entry["backdrop"]))
        )
        Image.fromarray(_over(ref, backdrop), mode="RGB").save(
            HERE / "originals" / f"{entry['name']}.png", optimize=True
        )


if __name__ == "__main__":
    main()
